            _ENDPOINT,
            data=json.dumps(payload, ensure_ascii=False).encode(\"utf-8\"),
            headers={
                \"Authorization\": \"Bearer \" + self._api_key,
                \"Content-Type\": \"application/json\",
                \"Accept\": \"application/json\",
            },
            method=\"POST\",
        )
        try:
