import unittest
import urllib.error
from unittest.mock import patch
import openai_client

class ClientTests(unittest.TestCase):
    def setUp(self):
        self.client = openai_client.OpenAIClient('dummy-key')

    def test_request_and_text(self):
        response = {'status': 'completed', 'output': [
            {'type': 'reasoning'},
            {'type': 'message', 'content': [
                {'type': 'output_text', 'text': 'Hello '},
                {'type': 'output_text', 'text': 'world'}]}]}
        with patch.object(self.client._opener, 'open', return_value=io.BytesIO(json.dumps(response).encode())) as mocked:
            self.assertEqual(self.client.send_prompt('Synthetic Unicode: café', model='test-model', instructions='Be brief', max_output_tokens=40), 'Hello world')
            request = mocked.call_args.args[0]
            payload = json.loads(request.data)
            self.assertEqual(payload['store'], False)
            self.assertEqual(payload['input'], 'Synthetic Unicode: café')
            self.assertEqual(payload['instructions'], 'Be brief')
            self.assertEqual(payload['max_output_tokens'], 40)
            self.assertEqual(request.full_url, 'https://api.openai.com/v1/responses')
            self.assertEqual(request.get_method(), 'POST')
            self.assertEqual(request.get_header('Authorization'), 'Bearer dummy-key')

    def test_error_privacy(self):
        error = urllib.error.HTTPError('https://api.openai.com', 401, 'sensitive body', {}, io.BytesIO(b'sensitive body'))
        with patch.object(self.client._opener, 'open', side_effect=error):
            with self.assertRaises(openai_client.OpenAIError) as caught:
                self.client.send_prompt('synthetic', model='test-model')
            self.assertEqual(str(caught.exception), 'OpenAI returned HTTP 401.')
            self.assertTrue(caught.exception.__suppress_context__)

    def test_validation(self):
        for timeout in (0, -1, float('inf'), float('nan'), True):
            with self.assertRaises(ValueError):
                openai_client.OpenAIClient('dummy-key', timeout=timeout)
        for tokens in (0, -1, True, 1.5):
            with self.assertRaises(ValueError):
                self.client.create_response('synthetic', model='test-model', max_output_tokens=tokens)
        with self.assertRaises(ValueError):
            openai_client.OpenAIClient('key\\nheader')

    def test_invalid_responses(self):
        for response in (b'not json', b'[]', b'{\"status\":\"failed\"}', b'{\"status\":\"incomplete\"}', b'{\"status\":\"completed\",\"output\":[]}'):
            with patch.object(self.client._opener, 'open', return_value=io.BytesIO(response)):
                with self.assertRaises(openai_client.OpenAIError):
                    self.client.send_prompt('synthetic', model='test-model')

    def test_redirects_disabled(self):
        handler = openai_client._NoRedirect()
        self.assertIsNone(handler.redirect_request(None, None, 302, '', {}, 'https://example.invalid'))

    def test_cli(self):
        with patch.dict('os.environ', {'OPENAI_API_KEY':'dummy-key'}), patch('sys.stdin', io.StringIO('synthetic')), patch('sys.stdout', new_callable=io.StringIO) as output, patch.object(openai_client.OpenAIClient, 'send_prompt', return_value='reply'):
            self.assertEqual(openai_client.main(['--model', 'test-model']), 0)
            self.assertEqual(output.getvalue(), 'reply\\n')

unittest.main()
